package ledger

import (
	"errors"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Entry is a single ledger transaction.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// Column widths used throughout the ledger layout.
const (
	dateColumnWidth      = 10
	descriptionColumnWidth = 25
	changeColumnWidth    = 13
)

var (
	errInvalidCurrency = errors.New("invalid currency")
	errInvalidLocale   = errors.New("invalid locale")
	errInvalidDate     = errors.New("invalid date")
)

var (
	supportedCurrencies = map[string]string{"USD": "$", "EUR": "€"}
	supportedLocales    = map[string]bool{"en-US": true, "nl-NL": true}
)

// FormatLedger renders a nicely formatted ledger for the given currency and
// locale. Entries are printed sorted by date, then description, then change.
// The input slice is never mutated.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	symbol, ok := supportedCurrencies[currency]
	if !ok {
		return "", errInvalidCurrency
	}
	if !supportedLocales[locale] {
		return "", errInvalidLocale
	}

	// Sort a copy so the caller's slice and its elements stay untouched.
	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.SliceStable(sorted, func(i, j int) bool {
		a, b := sorted[i], sorted[j]
		if a.Date != b.Date {
			return a.Date < b.Date
		}
		if a.Description != b.Description {
			return a.Description < b.Description
		}
		return a.Change < b.Change
	})

	var sb strings.Builder
	sb.WriteString(header(locale))
	for _, e := range sorted {
		line, err := formatEntry(symbol, locale, e)
		if err != nil {
			return "", err
		}
		sb.WriteString(line)
	}
	return sb.String(), nil
}

// header renders the column titles for the given locale.
func header(locale string) string {
	dateLabel, descLabel, changeLabel := "Date", "Description", "Change"
	if locale == "nl-NL" {
		dateLabel, descLabel, changeLabel = "Datum", "Omschrijving", "Verandering"
	}
	return leftPad(dateLabel, dateColumnWidth) + " | " +
		leftPad(descLabel, descriptionColumnWidth) + " | " +
		changeLabel + "\n"
}

// formatEntry renders a single ledger row.
func formatEntry(symbol, locale string, e Entry) (string, error) {
	date, err := formatDate(locale, e.Date)
	if err != nil {
		return "", err
	}
	change := formatChange(symbol, locale, e.Change)
	return date + " | " + formatDescription(e.Description) + " | " +
		rightPad(change, changeColumnWidth) + "\n", nil
}

// formatDate validates the "Y-m-d" date and renders it in the locale's
// display format.
func formatDate(locale, date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", errInvalidDate
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	if locale == "nl-NL" {
		return day + "-" + month + "-" + year, nil
	}
	return month + "/" + day + "/" + year, nil
}

// formatDescription truncates overlong descriptions and pads the rest so the
// column is a fixed width.
func formatDescription(description string) string {
	if len(description) > descriptionColumnWidth {
		return description[:22] + "..."
	}
	return description + strings.Repeat(" ", descriptionColumnWidth-len(description))
}

// formatChange renders the amount, applying the locale's grouping/decimal
// separators and sign conventions.
func formatChange(symbol, locale string, change int) string {
	negative := change < 0
	if negative {
		change = -change
	}

	cents := strconv.Itoa(change)
	// Guarantee a whole part and exactly two fraction digits.
	switch len(cents) {
	case 1:
		cents = "00" + cents
	case 2:
		cents = "0" + cents
	}
	whole := cents[:len(cents)-2]
	fraction := cents[len(cents)-2:]

	decimalSep, thousandSep := ".", ","
	if locale == "nl-NL" {
		decimalSep, thousandSep = ",", "."
	}
	number := groupThousands(whole, thousandSep) + decimalSep + fraction

	switch {
	case locale == "nl-NL" && negative:
		return symbol + " " + number + "-"
	case locale == "nl-NL":
		return symbol + " " + number + " "
	case negative:
		return "(" + symbol + number + ")"
	default:
		return symbol + number + " "
	}
}

// groupThousands inserts a separator every three digits of the whole part.
func groupThousands(whole, sep string) string {
	var b strings.Builder
	for i, c := range whole {
		if i > 0 && (len(whole)-i)%3 == 0 {
			b.WriteString(sep)
		}
		b.WriteByte(byte(c))
	}
	return b.String()
}

// leftPad pads s with trailing spaces up to width, measured in runes.
func leftPad(s string, width int) string {
	return s + strings.Repeat(" ", max(0, width-utf8.RuneCountInString(s)))
}

// rightPad pads s with leading spaces up to width, measured in runes.
func rightPad(s string, width int) string {
	return strings.Repeat(" ", max(0, width-utf8.RuneCountInString(s))) + s
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

